package br.com.equilibra.recurrence.api; import br.com.equilibra.recurrence.application.RecurrenceRuleService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;
@RestController @RequestMapping("/recurrences") @Tag(name="Recurrences") @SecurityRequirement(name="bearerAuth") public class RecurrenceRuleController{private final RecurrenceRuleService service;public RecurrenceRuleController(RecurrenceRuleService s){service=s;}@PostMapping public ResponseEntity<RecurrenceDtos.Response>create(@RequestBody RecurrenceDtos.Create r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping public List<RecurrenceDtos.Response>list(){return service.list();}@GetMapping("/{id}")public RecurrenceDtos.Response get(@PathVariable String id){return service.get(id);}@PutMapping("/{id}")public RecurrenceDtos.Response update(@PathVariable String id,@RequestBody RecurrenceDtos.Update r){return service.update(id,r);}@PostMapping("/{id}/pause")public RecurrenceDtos.Response pause(@PathVariable String id){return service.pause(id);}@PostMapping("/{id}/resume")public RecurrenceDtos.Response resume(@PathVariable String id){return service.resume(id);}@PostMapping("/{id}/end")public RecurrenceDtos.Response end(@PathVariable String id){return service.end(id);}@PostMapping("/{id}/cancel")public RecurrenceDtos.Response cancel(@PathVariable String id){return service.cancel(id);}}
